    if p.get('status')=='done' and openk: print('DONE PARENT, open kids:',pid,openk)
    if p.get('status') in ('pending','active','blocked') and not openk:
        print('ALL KIDS DONE, parent',p.get('status'),':',pid,'kids',[k['id'] for k in ks])
